import { useQuery } from '@tanstack/react-query';
import { PaginationType } from '@appTypes/app.type';
import ApiService from '@services/index';
import API_PATH from '@utils/api.path';
import axios from 'axios';

export const getUsers = async (params: PaginationType) => {
  const response = await axios.get('https://randomuser.me/api/', {
    withCredentials: true, // Nếu bạn cần gửi thông tin xác thực
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Content-Type': 'application/json',
    },
    params
  })
  console.log("response getUsers", response)
  return response;
}

export const useGetUsers = (params: PaginationType) => {
  return useQuery({
    queryKey: ['users'],
    queryFn: () => getUsers(params),
  });
}